CREATE TABLE IF NOT EXISTS signals(id BIGSERIAL PRIMARY KEY,candle_time TIMESTAMPTZ NOT NULL UNIQUE,signal_type TEXT NOT NULL CHECK(signal_type IN ('LONG','SHORT','SIN SEÑAL')),btc_price NUMERIC(18,8) NOT NULL,rsi NUMERIC(10,4),ema20 NUMERIC(18,8),ema50 NUMERIC(18,8),atr NUMERIC(18,8),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS paper_trades(id BIGSERIAL PRIMARY KEY,side TEXT NOT NULL CHECK(side IN ('LONG','SHORT')),entry_time TIMESTAMPTZ NOT NULL,entry_price NUMERIC(18,8) NOT NULL,quantity NUMERIC(24,12) NOT NULL,stop_price NUMERIC(18,8) NOT NULL,target_price NUMERIC(18,8) NOT NULL,exit_time TIMESTAMPTZ,exit_price NUMERIC(18,8),pnl_usd NUMERIC(18,8),exit_reason TEXT,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS one_open_paper_trade ON paper_trades((status)) WHERE status='OPEN';
CREATE TABLE IF NOT EXISTS bot_settings(id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1),reference_capital NUMERIC(18,2) NOT NULL DEFAULT 1000,risk_fraction NUMERIC(8,6) NOT NULL DEFAULT .0025,daily_loss_fraction NUMERIC(8,6) NOT NULL DEFAULT .01,timeframe TEXT NOT NULL DEFAULT '15m',updated_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO bot_settings(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
